'use strict';
// Tắm Tráng 6 — configured recipient and VietQR dynamic amount links.
// Quick Link image generated by vietqr.io. This does NOT verify a bank transfer.
module.exports=function paymentRecipient({pool}){
 const invalid=(message,status=400)=>Object.assign(Error(message),{status});
 async function get(){
  if(!pool)return null;
  const result=await pool.query('SELECT bank_bin,account_number,account_name,enabled FROM merchant_payment_settings WHERE singleton=true');
  return result.rows[0]||null;
 }
 async function publicRecipient(){
  const r=await get();
  return r?.enabled?{bankBin:r.bank_bin,accountNumber:r.account_number,accountName:r.account_name}:null;
 }
 function qrUrl(recipient,amount,reference){
  if(!recipient||!Number.isSafeInteger(amount)||amount<=0||amount>999999999999) return null;
  const bank=recipient.bankBin,account=recipient.accountNumber;
  if(!/^\d{6}$/.test(bank)||!/^\d{6,25}$/.test(account))return null;
  const info=String(reference||'').replace(/[^A-Za-z0-9 ]/g,'').slice(0,25)||'TAM TRANG 6';
  const name=String(recipient.accountName||'').slice(0,100);
  const query=new URLSearchParams({amount:String(amount),addInfo:info,accountName:name});
  return 'https://img.vietqr.io/image/'+bank+'-'+account+'-compact2.png?'+query.toString();
 }
 async function set(body){
  if(!pool)throw invalid('Cần cơ sở dữ liệu PostgreSQL để cấu hình thanh toán.',503);
  const bankBin=String(body.bankBin||'').trim();
  const accountNumber=String(body.accountNumber||'').trim();
  const accountName=String(body.accountName||'').trim();
  const enabled=body.enabled!==false;
  if(!/^\d{6}$/.test(bankBin))throw invalid('Mã BIN ngân hàng phải gồm 6 chữ số (ví dụ tra cứu từ ngân hàng).');
  if(!/^\d{6,25}$/.test(accountNumber))throw invalid('Số tài khoản phải gồm 6–25 chữ số.');
  if(accountName.length<2||accountName.length>100||/[\r\n<>]/.test(accountName))throw invalid('Tên chủ tài khoản không hợp lệ.');
  const r=await pool.query("INSERT INTO merchant_payment_settings(singleton,bank_bin,account_number,account_name,enabled) VALUES(true,$1,$2,$3,$4) ON CONFLICT(singleton) DO UPDATE SET bank_bin=excluded.bank_bin,account_number=excluded.account_number,account_name=excluded.account_name,enabled=excluded.enabled,updated_at=now() RETURNING bank_bin,account_number,account_name,enabled,updated_at",
  [bankBin,accountNumber,accountName,enabled]);
  return {bankBin:r.rows[0].bank_bin,accountNumber:r.rows[0].account_number,accountName:r.rows[0].account_name,enabled:r.rows[0].enabled,updatedAt:r.rows[0].updated_at};
 }
 return {get,publicRecipient,qrUrl,set};
};
